"""Command line entry point.

Commands:
  version                          print the package version
  help                             print this message
  build <input.jsonl> <snapshot>   build a deterministic inverted snapshot
  search <snapshot> "<query>"      run one boolean query against a snapshot

Exit codes: 0 success, 1 filesystem error (missing/unreadable input,
unwritable output), 2 invalid data (documents, snapshot or query). On error
the first stderr line starts with "error:" and no partial result is written
to stdout.
"""
import json
import sys

from . import __version__
from .errors import DataError
from .query import evaluate, parse
from .snapshot import Snapshot, build_from_lines, write_atomic

USAGE = """usage: python3 -m text_index_engine <command>

commands:
  version                                 print the package version
  help                                    print this message
  build <input.jsonl> <snapshot>          build an inverted-index snapshot
  search <snapshot> "<query>"             query a snapshot

exit codes:
  0  success
  1  filesystem error (missing/unreadable input, unwritable output)
  2  invalid data (documents, snapshot or query)
"""


def _data_error(exc: Exception) -> int:
    print(f"error: {exc}", file=sys.stderr)
    return 2


def _io_error(exc: OSError) -> int:
    print(f"error: {exc}", file=sys.stderr)
    return 1


def _cmd_build(args: list[str]) -> int:
    if len(args) != 2:
        print("error: build requires <input.jsonl> and <snapshot> paths",
              file=sys.stderr)
        return 2
    input_path, output_path = args
    try:
        with open(input_path, "r", encoding="utf-8") as fp:
            lines = fp.readlines()
    except UnicodeDecodeError as exc:
        return _data_error(DataError(f"input is not valid UTF-8: {exc}"))
    except OSError as exc:
        return _io_error(exc)

    try:
        data = build_from_lines(lines)
    except DataError as exc:
        return _data_error(exc)

    try:
        write_atomic(output_path, data)
    except OSError as exc:
        return _io_error(exc)
    return 0


def _cmd_search(args: list[str]) -> int:
    if len(args) != 2:
        print("error: search requires <snapshot> path and one query string",
              file=sys.stderr)
        return 2
    snapshot_path, query = args
    try:
        with open(snapshot_path, "rb") as fp:
            raw = fp.read()
    except OSError as exc:
        return _io_error(exc)

    try:
        snapshot = Snapshot.load(raw)
        node = parse(query)
        hits = set() if node is None else evaluate(node, snapshot)
        result = sorted(hits)
        output = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
    except DataError as exc:
        return _data_error(exc)

    sys.stdout.write(output + "\n")
    return 0


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    command = args[0] if args else "help"
    if command == "version":
        print(__version__)
        return 0
    if command in {"help", "-h", "--help"}:
        print(USAGE, end="")
        return 0
    if command == "build":
        return _cmd_build(args[1:])
    if command == "search":
        return _cmd_search(args[1:])
    print(f"unknown command: {command}", file=sys.stderr)
    print(USAGE, end="", file=sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Boolean query language: lexer, parser, set-based evaluator.

Grammar (explicit operators only, no implicit conjunction)::

    or_expr  := and_expr (OR and_expr)*
    and_expr := not_expr (AND not_expr)*
    not_expr := NOT not_expr | atom
    atom     := TERM | PHRASE | LPAREN or_expr RPAREN

Precedence is NOT > AND > OR. AND/OR/NOT are keywords only when written in
exact uppercase; lowercase forms are ordinary search terms. Query terms and
phrase terms go through the same normalization/tokenization as the indexed
text. Evaluation operates on sets of document ids; NOT's universe is the
full document set recorded in the snapshot.
"""
from .analysis import tokenize
from .errors import DataError

# Token kinds
T_TERM = "TERM"
T_PHRASE = "PHRASE"
T_AND = "AND"
T_OR = "OR"
T_NOT = "NOT"
T_LPAREN = "LPAREN"
T_RPAREN = "RPAREN"
T_EOF = "EOF"

_KEYWORDS = {"AND": T_AND, "OR": T_OR, "NOT": T_NOT}


class _Token:
    __slots__ = ("kind", "value")

    def __init__(self, kind, value):
        self.kind = kind
        self.value = value


def _lex(query: str) -> list[_Token]:
    tokens: list[_Token] = []
    i = 0
    n = len(query)
    while i < n:
        ch = query[i]
        if ch.isspace():
            i += 1
            continue
        if ch == "(":
            tokens.append(_Token(T_LPAREN, ch))
            i += 1
            continue
        if ch == ")":
            tokens.append(_Token(T_RPAREN, ch))
            i += 1
            continue
        if ch == '"':
            j = i + 1
            while j < n and query[j] != '"':
                j += 1
            if j >= n:
                raise DataError("query: unterminated quoted phrase")
            words = tokenize(query[i + 1:j])
            if not words:
                raise DataError(
                    "query: quoted phrase contains no searchable term")
            tokens.append(_Token(T_PHRASE, words))
            i = j + 1
            continue
        # Bare run up to the next delimiter.
        start = i
        while i < n and not query[i].isspace() and query[i] not in '()"':
            i += 1
        run = query[start:i]
        kind = _KEYWORDS.get(run)
        if kind is not None:
            tokens.append(_Token(kind, run))
            continue
        words = tokenize(run)
        if len(words) == 1:
            tokens.append(_Token(T_TERM, words[0]))
        elif not words:
            raise DataError(f"query: unknown lexical unit {run!r}")
        else:
            # e.g. "foo,bar": several tokens with no explicit operator.
            raise DataError(
                f"query: {run!r} splits into multiple terms without an operator")
    tokens.append(_Token(T_EOF, None))
    return tokens


class _Parser:
    def __init__(self, tokens: list[_Token]):
        self.tokens = tokens
        self.pos = 0

    def _peek(self) -> _Token:
        return self.tokens[self.pos]

    def _advance(self) -> _Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        node = self._parse_or()
        tok = self._peek()
        if tok.kind != T_EOF:
            if tok.kind == T_RPAREN:
                raise DataError("query: unmatched ')'")
            raise DataError("query: missing operator between operands")
        return node

    def _parse_or(self):
        left = self._parse_and()
        while self._peek().kind == T_OR:
            self._advance()
            right = self._parse_and()
            left = ("or", left, right)
        return left

    def _parse_and(self):
        left = self._parse_not()
        while self._peek().kind == T_AND:
            self._advance()
            right = self._parse_not()
            left = ("and", left, right)
        return left

    def _parse_not(self):
        tok = self._peek()
        if tok.kind == T_NOT:
            self._advance()
            return ("not", self._parse_not())
        return self._parse_atom()

    def _parse_atom(self):
        tok = self._peek()
        if tok.kind == T_TERM:
            self._advance()
            return ("term", tok.value)
        if tok.kind == T_PHRASE:
            self._advance()
            return ("phrase", tok.value)
        if tok.kind == T_LPAREN:
            self._advance()
            if self._peek().kind == T_RPAREN:
                raise DataError("query: missing operand inside parentheses")
            node = self._parse_or()
            closing = self._peek()
            if closing.kind != T_RPAREN:
                raise DataError("query: unbalanced parentheses")
            self._advance()
            return node
        if tok.kind == T_RPAREN:
            raise DataError("query: unmatched ')'")
        if tok.kind == T_EOF:
            raise DataError("query: missing operand")
        raise DataError(f"query: unexpected token {tok.value!r}")


def parse(query: str):
    """Parse a query string into an AST. Empty/whitespace-only returns None."""
    tokens = _lex(query)
    if len(tokens) == 1:  # only EOF
        return None
    return _Parser(tokens).parse()


def _phrase_docs(snapshot, words: list[str]) -> set[str]:
    first = snapshot.postings.get(words[0])
    if first is None:
        return set()
    candidates = set(first)
    for w in words[1:]:
        p = snapshot.postings.get(w)
        if p is None:
            return set()
        candidates &= p.keys()
        if not candidates:
            return set()
    hits: set[str] = set()
    for doc_id in candidates:
        first_positions = snapshot.postings[words[0]][doc_id]
        # Position sets for the later phrase words (sorted at build time).
        later = [set(snapshot.postings[w][doc_id]) for w in words[1:]]
        for start in first_positions:
            if all(start + k in later[k - 1] for k in range(1, len(words))):
                hits.add(doc_id)
                break
    return hits


def evaluate(node, snapshot) -> set[str]:
    kind = node[0]
    universe = snapshot.all_docs
    if kind == "term":
        posting = snapshot.postings.get(node[1])
        return set(posting) if posting is not None else set()
    if kind == "phrase":
        return _phrase_docs(snapshot, node[1])
    if kind == "not":
        return set(universe) - evaluate(node[1], snapshot)
    if kind == "and":
        return evaluate(node[1], snapshot) & evaluate(node[2], snapshot)
    if kind == "or":
        return evaluate(node[1], snapshot) | evaluate(node[2], snapshot)
    raise DataError(f"query: internal error, unknown node {kind!r}")

"""Deterministic inverted-index snapshot: build, serialize, load.

Canonical JSON representation (versioned)::

    {"version":1,"documents":["id",...],"terms":[
      {"term":"...","postings":[{"id":"...","positions":[0,2]}]}]}

Ordering is by Unicode code point throughout: documents and postings by the
original document id, terms by the normalized term. Serialization never
embeds timestamps, paths or other environment data, so the same document set
produces byte-identical snapshots regardless of input line order.
"""
import json
import os
import tempfile

from .analysis import tokenize
from .errors import DataError

SNAPSHOT_VERSION = 1

# Compact canonical form. Key order is fixed by construction; ensure_ascii
# keeps non-ASCII codepoints literal (stable across environments).
_SEPARATORS = (",", ":")


def _encode(obj) -> bytes:
    return (json.dumps(obj, ensure_ascii=False, separators=_SEPARATORS)
            + "\n").encode("utf-8")


def build_from_lines(lines) -> bytes:
    """Validate JSONL document lines and return canonical snapshot bytes.

    Each line must be a JSON object with non-empty unique string ``id`` and
    string ``text``. Raises DataError on any validation failure; nothing is
    written until the whole input has been validated.
    """
    # id -> tokens (dict also doubles as insertion-ordered duplicate check).
    documents: dict[str, list[str]] = {}
    seen_ids: set[str] = set()

    for lineno, line in enumerate(lines, start=1):
        try:
            doc = json.loads(line)
        except (json.JSONDecodeError, TypeError) as exc:
            raise DataError(f"line {lineno}: not a JSON document: {exc.msg}")
        if not isinstance(doc, dict):
            raise DataError(f"line {lineno}: document must be a JSON object")
        if "id" not in doc:
            raise DataError(f"line {lineno}: missing field 'id'")
        if "text" not in doc:
            raise DataError(f"line {lineno}: missing field 'text'")
        doc_id = doc["id"]
        text = doc["text"]
        if not isinstance(doc_id, str):
            raise DataError(f"line {lineno}: 'id' must be a string")
        if not isinstance(text, str):
            raise DataError(f"line {lineno}: 'text' must be a string")
        if doc_id == "":
            raise DataError(f"line {lineno}: 'id' must be non-empty")
        if doc_id in seen_ids:
            raise DataError(f"line {lineno}: duplicate id {doc_id!r}")
        seen_ids.add(doc_id)
        documents[doc_id] = tokenize(text)

    return _encode(_build_object(documents))


def _build_object(documents: dict[str, list[str]]):
    # term -> doc id -> positions
    terms: dict[str, dict[str, list[int]]] = {}
    for doc_id, tokens in documents.items():
        for position, term in enumerate(tokens):
            terms.setdefault(term, {}).setdefault(doc_id, []).append(position)

    term_objs = []
    for term in sorted(terms):
        postings = terms[term]
        term_objs.append({
            "term": term,
            "postings": [
                {"id": doc_id, "positions": postings[doc_id]}
                for doc_id in sorted(postings)
            ],
        })

    return {
        "version": SNAPSHOT_VERSION,
        "documents": sorted(documents),
        "terms": term_objs,
    }


def write_atomic(path: str, data: bytes) -> None:
    """Write bytes to path, replacing the target only after success.

    The temp file is created in the destination directory and fsynced before
    the atomic replace; on any failure the temp file is removed and any
    pre-existing target is left untouched.
    """
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(
        dir=directory, prefix=f".{os.path.basename(path)}.", suffix=".tmp")
    try:
        with os.fdopen(fd, "wb") as fp:
            fp.write(data)
            fp.flush()
            os.fsync(fp.fileno())
        os.replace(tmp_path, path)
        tmp_path = None
    finally:
        if tmp_path is not None:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


class Snapshot:
    """Loaded snapshot used by the search evaluator."""

    def __init__(self, doc_ids: list[str], postings: dict[str, dict[str, list[int]]]):
        self.doc_ids = doc_ids                      # already codepoint-sorted
        self.all_docs = frozenset(doc_ids)
        self.postings = postings                    # term -> doc id -> positions

    @classmethod
    def load(cls, raw: bytes | str) -> "Snapshot":
        try:
            obj = json.loads(raw)
        except (json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise DataError(f"snapshot is not valid JSON: {exc}")
        if not isinstance(obj, dict):
            raise DataError("snapshot: top-level value must be an object")
        version = obj.get("version")
        if not isinstance(version, int) or isinstance(version, bool):
            raise DataError("snapshot: missing or invalid 'version'")
        if version != SNAPSHOT_VERSION:
            raise DataError(
                f"unsupported snapshot version: {version} "
                f"(supported: {SNAPSHOT_VERSION})")

        doc_ids = obj.get("documents")
        terms = obj.get("terms")
        if not isinstance(doc_ids, list) or not isinstance(terms, list):
            raise DataError("snapshot: 'documents' and 'terms' must be arrays")

        # Documents: non-empty strings, unique, strictly increasing by
        # Unicode code point (the order build emits).
        seen: set[str] = set()
        prev_id = None
        for doc_id in doc_ids:
            if not isinstance(doc_id, str):
                raise DataError("snapshot: document ids must be strings")
            if doc_id == "":
                raise DataError("snapshot: document ids must be non-empty")
            if prev_id is not None and not doc_id > prev_id:
                raise DataError(
                    f"snapshot: document ids must be unique and strictly "
                    f"increasing by code point ({doc_id!r} after {prev_id!r})")
            seen.add(doc_id)
            prev_id = doc_id

        postings: dict[str, dict[str, list[int]]] = {}
        # Per document: every indexed position maps to the single term that
        # occupies it. Used to reject same-position multi-term postings and
        # non-continuous position coverage, neither of which build can emit.
        position_owner: dict[str, dict[int, str]] = {
            doc_id: {} for doc_id in doc_ids}

        prev_term = None
        for entry in terms:
            if (not isinstance(entry, dict)
                    or not isinstance(entry.get("term"), str)
                    or not isinstance(entry.get("postings"), list)):
                raise DataError("snapshot: malformed term entry")
            term = entry["term"]
            if term == "":
                raise DataError("snapshot: term must be non-empty")
            if prev_term is not None and not term > prev_term:
                raise DataError(
                    f"snapshot: terms must be unique and strictly increasing "
                    f"({term!r} after {prev_term!r})")
            # A v1 term is exactly what the current analyzer would produce
            # from it: one normalized token identical to the term itself.
            tokens = tokenize(term)
            if tokens != [term]:
                raise DataError(
                    f"snapshot: term {term!r} is not a single normalized "
                    f"analyzer term")
            prev_term = term

            if not entry["postings"]:
                raise DataError(
                    f"snapshot: term {term!r} has an empty postings list")

            term_postings: dict[str, list[int]] = {}
            prev_posting_id = None
            for p in entry["postings"]:
                if (not isinstance(p, dict)
                        or not isinstance(p.get("id"), str)
                        or not isinstance(p.get("positions"), list)):
                    raise DataError("snapshot: malformed posting")
                doc_id = p["id"]
                positions = p["positions"]
                if doc_id not in seen:
                    raise DataError(
                        f"snapshot: posting references unknown document "
                        f"{doc_id!r}")
                if prev_posting_id is not None and not doc_id > prev_posting_id:
                    raise DataError(
                        f"snapshot: postings for {term!r} must be unique and "
                        f"strictly increasing by document id ({doc_id!r} "
                        f"after {prev_posting_id!r})")
                prev_posting_id = doc_id

                if not positions:
                    raise DataError(
                        f"snapshot: empty positions for "
                        f"{term!r}/{doc_id!r}")
                prev_pos = None
                for x in positions:
                    if not isinstance(x, int) or isinstance(x, bool) or x < 0:
                        raise DataError(
                            "snapshot: positions must be non-negative "
                            "integers (not booleans)")
                    if prev_pos is not None and x <= prev_pos:
                        raise DataError(
                            f"snapshot: positions for {term!r}/{doc_id!r} "
                            f"must be strictly increasing")
                    prev_pos = x
                    owners = position_owner[doc_id]
                    other = owners.get(x)
                    if other is not None:
                        raise DataError(
                            f"snapshot: position {x} in document {doc_id!r} "
                            f"claimed by both {other!r} and {term!r}")
                    owners[x] = term

                term_postings[doc_id] = positions
            postings[term] = term_postings

        # Cross-term coverage per document: a tokenized document's positions
        # are exactly 0..n-1, each owned by one term, with no gaps; a document
        # with zero tokens must never be referenced by a posting.
        for doc_id in doc_ids:
            owners = position_owner[doc_id]
            if not owners:
                # No posting references this document: it is an empty-text
                # document, which is the only build output with zero tokens.
                continue
            # Positions are distinct non-negative ints all <= max, so a count
            # of max+1 holds exactly when they fill the whole run 0..max.
            max_pos = max(owners)
            if len(owners) != max_pos + 1:
                raise DataError(
                    f"snapshot: positions for document {doc_id!r} must form a "
                    f"continuous run 0..{max_pos} "
                    f"(got {len(owners)} position(s))")

        return cls(list(doc_ids), postings)

"""Shared text processing: Unicode NFKC normalization, casefold, tokenization.

A token is a maximal run of Unicode letters or decimal digits, recognized
*after* normalization (so NFKC-composed characters tokenize as one unit).
Empty/whitespace-only text yields zero tokens while the document is still
indexed (so NOT can cover it).
"""
import unicodedata


def normalize(text: str) -> str:
    """NFKC normalize, casefold. Shared by build and search."""
    return unicodedata.normalize("NFKC", text).casefold()


def tokenize(text: str) -> list[str]:
    """Return normalized tokens in zero-based document order.

    A token is a maximal contiguous run of codepoints whose Unicode general
    category starts with L (letter) or N (number: Nd/Nl/No). Fractions,
    roman numerals, superscript digits etc. are handled by NFKC beforehand.
    """
    tokens: list[str] = []
    run: list[str] = []

    def _is_token_char(ch: str) -> bool:
        # L* = letter (Lu Ll Lt Lm Lo), N* = number (Nd Nl No).
        return unicodedata.category(ch)[0] in ("L", "N")

    for ch in normalize(text):
        if _is_token_char(ch):
            run.append(ch)
        else:
            if run:
                tokens.append("".join(run))
                run = []
    if run:
        tokens.append("".join(run))
    return tokens

